/** Canonical cross-client rule contract, generated by the web authority. */
import { mkdirSync, writeFileSync } from "node:fs";
import { legalMoves, newGame, playMove, type Game, type Piece } from "../lib/game";

let seed = 0x13579;
const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
const fixtures: { game: Game; legal: ReturnType<typeof legalMoves>; chosen: { from: number; path: number[] } | null; after: Game | null }[] = [];
function record(game: Game) {
  const legal = legalMoves(game.board, game.turn);
  const chosen = legal.length && !game.winner ? legal[Math.floor(random() * legal.length)] : null;
  const after = chosen ? playMove(game, chosen.from, chosen.path) : null;
  fixtures.push({ game, legal, chosen: chosen ? { from: chosen.from, path: chosen.path } : null, after });
  return after;
}
for (let match = 0; match < 4; match++) {
  let game = newGame(`parity-${match}`);
  for (let ply = 0; ply < 40 && !game.winner; ply++) { const next = record(game); if (!next) break; game = next; }
}
const sparse: Record<number, Piece>[] = [
  { 48: 1, 40: -1, 24: -1, 54: 1, 46: -1 },
  { 27: 2, 25: -1, 29: -1 },
  { 18: 1, 10: -1, 3: -1, 7: -1 },
  { 56: 2, 32: -1, 55: -2 },
  { 43: 1, 35: -1, 28: -1 },
  { 40: 2, 15: -1 },
  { 40: 1, 15: -1 },
];
sparse.forEach((pieces, i) => record({ ...newGame(`sparse-${i}`), board: Object.assign(Array<Piece>(64).fill(0), pieces) }));
mkdirSync("mobile/test/fixtures", { recursive: true });
writeFileSync("mobile/test/fixtures/web_engine.json", JSON.stringify(fixtures));
console.log(`Wrote ${fixtures.length} web-engine contract positions for the Flutter tests.`);
